arguments.command:
SYMDIR="/tmp/sv-028c0c3ce0c242b3931ba9c22dc41b3b/symbols"
DBG="$SYMDIR/libmonosgen-2.0.so.dbg"

# Use a simpler approach - get sorted symbols and find what contains 0x2f4b20 and 0x2f4c84
nm -n -C "$DBG" 2>/dev/null | awk '
/^[0-9a-f]+ [tTwW]/ {
  addr = strtonum("0x"$1)
  name = $3
  for (i=4; i<=NF; i++) name = name " " $i
  if (addr <= 0x2f4b20) { last1_addr=$1; last1_name=name }
  if (addr <= 0x2f4c84) { last2_addr=$1; last2_name=name }
  if (addr > 0x2f4b20 && !f1) { print "0x2f4b20 -> " last1_name " (at 0x" last1_addr ", offset +" strtonum("0x2f4b20")-strtonum("0x"last1_addr) ")"; f1=1 }
  if (addr > 0x2f4c84 && !f2) { print "0x2f4c84 -> " last2_name " (at 0x" last2_addr ", offset +" strtonum("0x2f4c84")-strtonum("0x"last2_addr) ")"; f2=1 }
}' 2>/dev/null

